import {buildComparison,differences} from './comparison-model.mjs';
const q=s=>document.querySelector(s),banks=['normal','fault'],ready=new Set();
let experiment=buildComparison(),index=0,playing=false,elapsed=0,last=0,raf=0;
const value=(s,k)=>['x','y'].includes(k)?(s[k]*100).toFixed(1)+' mm':typeof s[k]==='boolean'?Number(s[k]):s[k];
const names={x:'posición A',y:'posición B',i0:'a0',i1:'a1',i2:'b0',i3:'b1',q:'YA',qB:'YB',pressure:'presión',pressureOK:'PS',fault:'FALLO',state:'etapa'};
const explanations={pressure:'La presión cae bajo 3 bar: PS pasa a 0 y el PLC retira ambas salidas en ese scan. Sin aire el pistón queda inmóvil; la referencia continúa.',jam:'A deja de moverse aunque YA siga activa. La diferencia física aparece antes de la alarma: al faltar a1 durante carrera + 1 s, el PLC dispara el timeout.',sensor:'A llega al extremo, pero a1 pierde señal por intervalos de 140 ms. El TON se reinicia cuando a1 cae; el ciclo normal continúa y el averiado termina en timeout.'};
function show(){const pair=experiment.frames[index];q('#cursor').max=experiment.frames.length-1;q('#cursor').value=index;q('#clock').textContent=pair.normal.time.toFixed(2)+' s';q('#play').textContent=playing?'Pausar ambos':'Reproducir ambos';q('#milestones').textContent='Primera diferencia: '+(experiment.first*.02).toFixed(2)+' s · Alarma: '+(experiment.alarm*.02).toFixed(2)+' s · Fin de referencia: '+experiment.frames.at(-1).normal.time.toFixed(2)+' s';const keys=differences(pair.normal,pair.fault);q('#delta').textContent=keys.length?'Normal / fallo → '+keys.map(k=>names[k]+': '+value(pair.normal,k)+' / '+value(pair.fault,k)).join(' · '):'Sin diferencias observables en este scan.';q('#explain').textContent=index>=experiment.first?explanations[experiment.kind]:'Ambos bancos parten de origen, con 4 bar, la misma receta y la misma orden de Marcha.';for(const bank of banks)if(ready.has(bank))q('#'+bank).contentWindow.postMessage({type:'comparison-scan',snapshot:pair[bank]},location.origin);}
function stop(){playing=false;cancelAnimationFrame(raf);raf=0;last=0;}
function seek(i){stop();index=Math.max(0,Math.min(experiment.frames.length-1,i));elapsed=index*.02;show();}
function loop(now){if(!playing)return;if(last)elapsed+=Math.min((now-last)/1000,.1)*Number(q('#rate').value);last=now;const next=Math.min(experiment.frames.length-1,Math.floor((elapsed+1e-9)/.02));if(index!==next){index=next;show();}if(index===experiment.frames.length-1){stop();show();return;}raf=requestAnimationFrame(loop);}
q('#play').onclick=()=>{if(playing){stop();show();return;}if(index===experiment.frames.length-1)seek(0);playing=true;elapsed=index*.02;last=0;show();raf=requestAnimationFrame(loop);};
q('#cursor').oninput=e=>seek(Number(e.target.value));q('#first').onclick=()=>seek(experiment.first);q('#alarm').onclick=()=>seek(experiment.alarm);q('#prev').onclick=()=>seek(index-1);q('#next').onclick=()=>seek(index+1);q('#restart').onclick=()=>seek(0);
q('#case').onchange=e=>{stop();experiment=buildComparison(e.target.value);seek(0);};
window.addEventListener('message',e=>{if(e.origin!==location.origin)return;const bank=banks.find(k=>q('#'+k).contentWindow===e.source);if(!bank)return;if(e.data?.type==='comparison-ready'){ready.add(bank);q('#play').disabled=ready.size!==2;show();}if(e.data?.type==='concept-height'&&Number.isFinite(e.data.height))q('#'+bank).style.height=Math.min(14000,Math.max(500,e.data.height))+'px';});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();show();}});
window.comparisonDebug=()=>({index,playing,ready:[...ready],experiment});show();
